+
+function reportTemplateRenderFailure(context: {
+  error: unknown;
+  merchantId: string;
+  templateId: string;
+}) {
+  const errorReporter = getErrorReporter();
+
+  if (!errorReporter) {
+    return;
+  }
+
+  errorReporter.captureException?.(context.error, {
+    tags: {
+      merchantId: context.merchantId,
+      templateId: context.templateId,
